                        "extract_patterns",
                        "get_applicable_procedures",
                        "get_applicable_skills",
                        "apply_procedure",
                        "create_skill",
                        "update_skill_experience",
                        "log_experience",
                        "get_learning_suggestions",
                        "get_learning_state",
                        "get_top_skills",
                        "suggest_actions_for_context",
                        "clear_observations"
